{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event(str(i), 1, False) for i in range(3)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 6), (3, 7), (10, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["\n", "   # comment, with, commas", "  a , -2 , 1  ",
             "b, 0, 0", " c , 7 ,  ", "   "]
    assert parse_transcript_log(lines) == [event("a", -2, True), event("b", 0, False),
                                           event("c", 7, None)]


@pytest.mark.parametrize("bad_line", ["too,few", "too,many,fields,here", "id,not-day,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", "  ", "ok,1,0", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    first = event("a", 0, True)
    last = event("a", 2, False)
    b = event("b", 2, True)
    c = event("c", 1, None)
    assert dedupe_transcripts([first, b, c, last]) == [c, last, b]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_fills_range_and_ignores_outside():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, False), event("e", 2, None), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("a", 1, True), event("b", 4, False)],
              "b": [event("c", 2, True)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "a": [event("a", 1, True)],
              "empty": [], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_names():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_only_consecutive_positive_counts():
    assert longest_flag_streak([1, 2, 0, 1, -1, 3, 4, 5]) == 3
    assert longest_flag_streak([-1, 0, -2]) == 0
    assert longest_flag_streak([]) == 0
